// RemoveAdPackage relationship.
// Sets o.R.AdPackage to nil.
// Removes o from all passed in related items' relationships struct.
func (o *FeaturedAd) RemoveAdPackage(ctx context.Context, exec boil.ContextExecutor, related *AdPackage) error {
	var err error

	queries.SetScanner(&o.AdPackageID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("ad_package_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.AdPackage = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.FeaturedAds {
		if queries.Equal(o.AdPackageID, ri.AdPackageID) {
			continue
		}

		ln := len(related.R.FeaturedAds)
		if ln > 1 && i < ln-1 {
			related.R.FeaturedAds[i] = related.R.FeaturedAds[ln-1]
		}
		related.R.FeaturedAds = related.R.FeaturedAds[:ln-1]
		break
	}
	return nil
}

